parameters.query:
SELECT t.id, t.batch_id, t.row_index, t.theme, t.status, t.error_message, r.content, b.file_name
FROM tasks t
LEFT JOIN responses r ON r.task_id = t.id
JOIN batchs b ON b.id = t.batch_id
WHERE t.batch_id = {{ Number($json.batch_id) }}
ORDER BY t.row_index;

