const batchId = $('Check Batch Completion').first().json.batch_id;

// Le lot est garanti complet par le node IF : toutes les lignes sont exploitables
const rows = $('Get Batch Articles').all().map((i) => i.json);

const baseName = String(rows[0]?.file_name ?? '').replace(/\.[^./\\]+$/, '');
const safeName =
  baseName.replace(/[^\p{L}\p{N}._-]+/gu, '_').replace(/^[._]+|_+$/g, '') ||
  'batch-' + batchId;

const PAGE_BREAK = '```{=openxml}\n<w:p><w:r><w:br w:type="page"/></w:r></w:p>\n```';

// Bloc d'une seule ligne, courte, sans ponctuation finale = intertitre
const isHeading = (b) => !b.includes('\n') && b.length < 150 && !/[.!?:;,]$/.test(b);

const articles = rows.map((r) => {
  const text = String(r.content).replace(/\r\n/g, '\n').trim();
  const [first, ...restLines] = text.split('\n');
  const title = (first || r.theme || '').trim();

  const out = ['# ' + title, ''];
  const blocks = restLines.join('\n').split(/\n{2,}/).map((b) => b.trim()).filter(Boolean);
  for (const b of blocks) {
    out.push(isHeading(b) ? '## ' + b : b.replace(/\n/g, ' '));
    out.push('');
  }
  return out.join('\n');
});

const markdown = articles.join('\n' + PAGE_BREAK + '\n\n');

return [{
  json: {
    batch_id: batchId,
    safe_name: safeName,
    md_path: '/files/output/batch-' + batchId + '.md',
    docx_path: '/files/output/' + safeName + '.docx',
  },
  binary: {
    data: {
      data: Buffer.from(markdown, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: 'batch-' + batchId + '.md',
    },
  },
}];

const batchId = $('When Called').first().json.batch_id;
const rows = $input.all().map((i) => i.json).filter((r) => r.id !== undefined);

// Une tâche est terminée seulement si SUCCESS et contenu non vide
const isDone = (r) => r.status === 'SUCCESS' && r.content;
const done = rows.filter(isDone);
const missing = rows.filter((r) => !isDone(r));
const complete = rows.length > 0 && missing.length === 0;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = (r) => (r.status === 'QUEUED' ? 'non traitée' : r.status === 'ERROR' ? 'en erreur' : 'réponse vide');

// Message Telegram (HTML), limité pour rester sous les 4096 caractères
let alert_message = '';
if (!complete) {
  const MAX_LIST = 15;
  const head =
    rows.length === 0
      ? '⚠️ Lot #' + batchId + ' : aucune tâche trouvée en base. Aucun fichier généré.'
      : '⚠️ Lot #' + batchId + ' incomplet : ' + done.length + '/' + rows.length + ' articles prêts. Aucun fichier généré.';
  const list = missing.slice(0, MAX_LIST).map((r) => {
    const err = r.error_message ? ' — ' + esc(String(r.error_message).slice(0, 100)) : '';
    return '• Ligne ' + r.row_index + ' : ' + esc(String(r.theme).slice(0, 80)) + ' (' + label(r) + ')' + err;
  });
  const more = missing.length > MAX_LIST ? '\n… et ' + (missing.length - MAX_LIST) + ' autre(s).' : '';
  alert_message =
    [head, '', ...list].join('\n') + more + '\n\nLes articles réussis restent en base (table responses).';
}

return [{
  json: {
    batch_id: batchId,
    complete,
    alert_message,
    stats: {
      total: rows.length,
      success: done.length,
      error: missing.length,
      failed_tasks: missing.map((f) => ({ id: f.id, theme: f.theme, status: f.status, error: f.error_message })),
    },
  },
}];
